add('expr_distribute','ma_expr',()=>{let a=rand(2,7),b=rand(2,6),c=rand(-8,8),d=rand(2,6),e=rand(2,7),f=rand(-8,8);return{type:'text',prompt:`次の式を整理しなさい。\n${a}(${linear(b,c)})−${d}(${linear(e,f)})`,answer:linear(a*b-d*e,a*c-d*f),grader:'polynomial',explanation:`前のかっこは ${linear(a*b,a*c)}、後ろのかっこ全体は ${linear(-d*e,-d*f)} になります。\n文字の係数：${a*b}−${d*e}=${a*b-d*e}\n定数項：${a*c}−(${d*f})=${a*c-d*f}\nかっこの前のマイナスを定数項にも掛けます。`}});
