add('expr_decimal','ma_expr',()=>{let a=rand(1,8),b=rand(1,9),c=rand(1,8);let k=(a*2+c)/10,constant=(-a*b+3*c)/10;return{type:'text',prompt:`次の式を整理しなさい。\n${(a/10).toFixed(1)}(2x−${b})＋${(c/10).toFixed(1)}(x＋3)`,answer:linear(k,constant),grader:'polynomial',explanation:`それぞれの項へ分配します。xの係数は ${a/10}×2＋${c/10}=${k}。定数項は −${a/10}×${b}＋${c/10}×3=${constant} です。`}});
add('eq_brackets','ma_eq',()=>{let a=rand(2,7),b=rand(2,5),c=rand(-8,8),d=rand(1,a*b-1),x=rand(-8,9),right=(a*b-d)*x+a*c;return{type:'text',prompt:`次の一次方程式を解きなさい。\n${a}(${linear(b,c)})＝${linear(d,right)}\n答えは x=数 の形で。`,answer:`x=${x}`,grader:'equation',variable:'x',value:x,explanation:`かっこを外すと ${linear(a*b,a*c)}＝${linear(d,right)}。\n移項して ${a*b-d}x＝${right-a*c}。\n両辺を ${a*b-d} で割ると x=${x}。\n数だけではなく、x= を付けて答えます。`}});
add('eq_fractions','ma_eq',()=>{let a=rand(1,5),c=rand(1,5);if(3*a===2*c)c++;let x=rand(-5,8),b=rand(-6,6),d=((3*a-2*c)*x+3*b)/2;return{type:'text',prompt:`次の一次方程式を解きなさい。\n(${linear(a,b)})/2＝(${linear(c,d)})/3\n答えは x=数 の形で。`,answer:`x=${x}`,grader:'equation',variable:'x',value:x,explanation:`両辺に6を掛けると 3(${linear(a,b)})＝2(${linear(c,d)})。\n${3*a-2*c}x＝${2*d-3*b} より x=${x}。分母を払うときは、分子の全体に数を掛けます。`}});
add('eq_percent','ma_eq',()=>{let total=rand(2,5)*100,x=rand(1,total/100-1)*100,grams=Math.round((.03*x+.07*(total-x))*100)/100;return{type:'text',prompt:`次の方程式を解きなさい。\n(3/100)x＋(7/100)(${total}−x)＝${grams}\n答えは x=数 の形で。`,answer:`x=${x}`,grader:'equation',variable:'x',value:x,explanation:`両辺に100を掛けます。\n3x＋7(${total}−x)＝${grams*100}\n−4x＋${7*total}＝${grams*100}\n−4x＝${grams*100-7*total} より x=${x}。`}});
