function kite(labels=['A','B','C','D']){let[a,b,c,d]=labels;return `<svg viewBox="0 0 420 260" role="img" aria-label="対角線で二つの三角形に分かれた四角形。対応する二組の辺が等しい。"><path d="M70 130 L180 30 L350 130 L180 230 Z" fill="#edf3ff" stroke="#365b94" stroke-width="3"/><path d="M70 130H350" stroke="#365b94" stroke-width="2"/><text x="47" y="136">${a}</text><text x="176" y="22">${b}</text><text x="358" y="136">${c}</text><text x="176" y="253">${d}</text><path d="M120 76l12 12 M120 184l12-12 M255 84l8-14 M263 89l8-14 M255 176l8 14 M263 171l8 14" fill="none" stroke="#365b94" stroke-width="2"/></svg>`.replace(' M258  seventy','')}
choice('cong_sss','ma_cong','図でAB＝AD、BC＝DCです。△ABCと△ADCが合同といえる条件は？','三辺がそれぞれ等しい',['二辺とその間の角がそれぞれ等しい','三つの角がそれぞれ等しい','一辺が等しい'],'ACは共通なのでAC＝AC。仮定の2組と合わせて3組の辺が等しくなります。',{diagram:kite()});
choice('cong_common','ma_cong','△ABCと△ADCで、AC＝ACといえる理由は？','共通な辺だから',['平行だから','対頂角だから','合同な三角形の対応する辺だから'],'合同を証明する前なので、合同を理由にしてはいけません。ACは両方の三角形が共有する辺です。',{diagram:kite()});
text('cong_order','ma_cong','AB＝DE、BC＝EF、AC＝DFです。△ABC≡△（　）となるよう、対応する頂点を3文字で答えなさい。','DEF','AはD、BはE、CはFに対応します。',{alt:['ＤＥＦ'],diagram:'<svg viewBox="0 0 440 180" role="img" aria-label="三角形ABCと三角形DEF"><path d="M30 150L95 25L180 150Z M245 150L310 25L395 150Z" fill="#eef4ff" stroke="#365b94" stroke-width="3"/><g font-size="18"><text x="88" y="20">A</text><text x="10" y="168">B</text><text x="183" y="168">C</text><text x="303" y="20">D</text><text x="225" y="168">E</text><text x="400" y="168">F</text></g></svg>'});
choice('cong_sas','ma_cong','AB＝DE、AC＝DF、∠BAC＝∠EDFが分かっています。使える合同条件は？','二辺とその間の角がそれぞれ等しい',['三辺がそれぞれ等しい','二辺とどこかの角が等しい','三つの角がそれぞれ等しい'],'∠BACはABとACの間の角、∠EDFはDEとDFの間の角です。');
choice('cong_not','ma_cong','次のうち、それだけでは三角形の合同を保証できないものは？','三つの角がそれぞれ等しい',['三辺がそれぞれ等しい','二辺とその間の角がそれぞれ等しい'],'角が同じでも大きさが違う三角形が作れます。辺の長さに関する条件も必要です。');
rubric('proof_kite','ma_proof','AB＝AD、BC＝DCのとき、△ABC≡△ADCを証明しなさい。図は模式図です。','△ABCと△ADCにおいて、\n仮定よりAB＝AD、BC＝DC。\n共通な辺なのでAC＝AC。\n以上より三辺がそれぞれ等しいので、△ABC≡△ADC。',['比較する三角形を△ABCと△ADCと書いた','AB＝AD、BC＝DCを仮定として挙げた','AC＝ACに「共通な辺」という理由を付けた','「三辺がそれぞれ等しい」と合同条件を書いた','対応順をそろえて△ABC≡△ADCと結論を書いた'],'辺を挙げるだけでなく、理由と合同条件をつなげます。',{diagram:kite()});
rubric('proof_sas','ma_proof','△ABCと△DEFで、AB＝DE、AC＝DF、∠BAC＝∠EDFが仮定です。この2つの三角形が合同であることを証明しなさい。','△ABCと△DEFにおいて、仮定よりAB＝DE、AC＝DF、∠BAC＝∠EDF。\n二辺とその間の角がそれぞれ等しいので、△ABC≡△DEF。',['比較する2つの三角形を書いた','仮定の2組の辺と1組の角を正しく挙げた','二辺と「その間の角」がそれぞれ等しいと書いた','△ABC≡△DEFと対応順をそろえた'],'「その間の角」を省かず書くことが重要です。',{diagram:'<svg viewBox="0 0 440 180" role="img" aria-label="三角形ABCとDEF。ABとDE、ACとDF、AとDの角が等しい"><path d="M30 150L95 25L180 150Z M245 150L310 25L395 150Z" fill="#eef4ff" stroke="#365b94" stroke-width="3"/><g font-size="18"><text x="88" y="20">A</text><text x="10" y="168">B</text><text x="183" y="168">C</text><text x="303" y="20">D</text><text x="225" y="168">E</text><text x="400" y="168">F</text></g></svg>'});
